SELECT mbcj.id, mbcj.cloudcut_name AS cloudcutName, mbcj.workshop_id AS workshopId, mbcj.parent_id AS parentId, mbcj.job_type AS jobType, mbw.name AS workshopName FROM mes_building_cloudcut_job mbcj LEFT JOIN mes_building_workshop mbw ON mbcj.workshop_id = mbw.id AND mbw.bool_delete_enum = 0 WHERE mbcj.bool_delete_enum = 0
AND mbcj.cloudcut_name LIKE CONCAT('%',#{mesBuildingCloudcutJobDTO.cloudcutName},'%')
AND mbcj.workshop_id = #{mesBuildingCloudcutJobDTO.workshopId}
